function roundRect(c,x,y,w,h,r){c.beginPath();c.roundRect(x,y,w,h,r);c.fill()}
function arena(){const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#1a1b27');g.addColorStop(.47,'#29212a');g.addColorStop(1,'#14151d');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
// overhead arena lights
for(let i=0;i<5;i++){const x=W*(.1+i*.2),rad=W*.17;let lg=ctx.createRadialGradient(x,H*.11,0,x,H*.57,rad);lg.addColorStop(0,'rgba(250,220,171,.17)');lg.addColorStop(1,'rgba(250,220,171,0)');ctx.fillStyle=lg;ctx.beginPath();ctx.moveTo(x-25,0);ctx.lineTo(x+25,0);ctx.lineTo(x+rad,H*.58);ctx.lineTo(x-rad,H*.58);ctx.fill();ctx.fillStyle='#ffe6bb';ctx.shadowColor='#ffe6bb';ctx.shadowBlur=22;ctx.beginPath();ctx.ellipse(x,H*.105,20,5,0,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0}
// dim crowd seats
ctx.fillStyle='#1a1822';ctx.fillRect(0,H*.36,W,H*.32);for(let y=H*.39;y<H*.66;y+=13){for(let x=(y%26?0:8);x<W;x+=17){let n=Math.sin(x*.17+y*.71);ctx.fillStyle=['#47343e','#344047','#695144','#343543','#87694a'][Math.floor(Math.abs(n*4.9))%5];ctx.globalAlpha=.36+Math.abs(n)*.32;ctx.beginPath();ctx.arc(x,y,2.4,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b9a783';ctx.globalAlpha=.3;ctx.fillRect(x-2,y+2,4,4)}}ctx.globalAlpha=1;
// wall signage
ctx.fillStyle='#201d25';ctx.fillRect(0,H*.58,W,H*.13);ctx.strokeStyle='#51414a';ctx.lineWidth=2;ctx.strokeRect(W*.08,H*.59,W*.84,H*.105);ctx.fillStyle='#d9b866';ctx.font=`900 ${Math.max(11,W*.014)}px 'Barlow Condensed',sans-serif`;ctx.textAlign='center';ctx.fillText('WOBBLE BOWL   •   EST. 1987   •   WOBBLE BOWL   •   EST. 1987',W/2,H*.645);
// ring mat and perspective
ctx.fillStyle='#11131a';ctx.beginPath();ctx.moveTo(W*.03,H*.62);ctx.lineTo(W*.97,H*.62);ctx.lineTo(W*1.12,H);ctx.lineTo(-W*.12,H);ctx.closePath();ctx.fill();let mat=ctx.createLinearGradient(0,H*.64,0,H);mat.addColorStop(0,'#45404a');mat.addColorStop(.48,'#36323d');mat.addColorStop(1,'#292731');ctx.fillStyle=mat;ctx.beginPath();ctx.moveTo(W*.08,H*.645);ctx.lineTo(W*.92,H*.645);ctx.lineTo(W*1.08,H);ctx.lineTo(-W*.08,H);ctx.closePath();ctx.fill();
// mat stitch marks and central badge
ctx.save();ctx.globalAlpha=.2;ctx.strokeStyle='#a49ba0';ctx.lineWidth=1;for(let i=-6;i<=6;i++){ctx.beginPath();ctx.moveTo(W/2+i*W*.065,H*.65);ctx.lineTo(W/2+i*W*.14,H);ctx.stroke()}ctx.beginPath();ctx.ellipse(W/2,H*.82,W*.13,H*.09,0,0,Math.PI*2);ctx.stroke();ctx.restore();ctx.strokeStyle='#c2b9ae';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(0,H*.667);ctx.lineTo(W,H*.667);ctx.stroke();
// ropes
for(let i=0;i<3;i++){let y=H*(.49+i*.066);ctx.strokeStyle=['#fa554d','#f4e3c2','#43d8cd'][i];ctx.lineWidth=i===1?4:3;ctx.globalAlpha=.84;ctx.beginPath();ctx.moveTo(0,y);ctx.quadraticCurveTo(W*.52,y-8,W,y+3);ctx.stroke()}ctx.globalAlpha=1;
// corner posts
for(const x of [W*.08,W*.92]){ctx.fillStyle='#ddd0b6';roundRect(ctx,x-7,H*.47,14,H*.21,4);ctx.fillStyle='#fa554d';roundRect(ctx,x-13,H*.51,26,34,4);ctx.fillStyle='#f0e2c7';ctx.font=`800 ${Math.max(8,W*.009)}px sans-serif`;ctx.textAlign='center';ctx.fillText('RR',x,H*.51+22)}
// slight vignette
const vg=ctx.createRadialGradient(W/2,H*.52,H*.18,W/2,H*.52,H*.77);vg.addColorStop(.55,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(0,0,0,.49)');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H)}
function limb(ax,ay,bx,by,width,color,outline='#17161d'){ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=outline;ctx.lineWidth=width+4;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(bx,by);ctx.stroke();ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();ctx.moveTo(ax,ay);ctx.lineTo(bx,by);ctx.stroke();ctx.fillStyle=color;ctx.beginPath();ctx.arc(ax,ay,width*.49,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(bx,by,width*.5,0,Math.PI*2);ctx.fill()}
function drawFighter(f,t){const floor=H*.785,scale=Math.min(W/1000,H/650)*1.13,unit=scale;const x=f.x*W;let lean=f.hit>0?-Math.sin(f.hit*10)*.19:Math.sin(t*3+(f===player?0:1))*.035;if(f.punch>0)lean+=f.face*(f.punchType==='hook'?.15:.1)*Math.sin(Math.PI*(1-f.punch/(f.punchType==='hook'?.46:.29)));if(f.guard)lean-=f.face*.07;if(f.dodge>0)lean-=f.face*.16;
ctx.save();ctx.translate(x,floor+Math.max(0,f.fall)*0);ctx.scale(unit*(f.face===-1?-1:1),unit);ctx.rotate(lean);const bob=Math.sin(t*6+(f.face<0?1:0))*2;const dead=f.fall>0;ctx.globalAlpha=1;
// shadow
ctx.save();ctx.scale(f.fall>0?1.5:1,1);ctx.fillStyle='#09090db0';ctx.beginPath();ctx.ellipse(0,2,47,10,0,0,Math.PI*2);ctx.fill();ctx.restore();
if(dead){ctx.rotate(-.8);ctx.translate(10,4)}
// legs, staggered wobbly stance
let sway=Math.sin(t*4+(f.face<0?2:0))*2,step=(keys.a||keys.d)&&f===player?Math.sin(t*14)*6:0;
limb(-12, -38, -18+step,-5,13,'#dc9e77');limb(-18+step,-7,-25+step,-1,12,'#201e27');limb(14,-38,22-sway,-7,14,'#eab088');limb(22-sway,-7,31-sway,0,13,'#201e27');
// shorts
ctx.fillStyle=f.shorts;ctx.strokeStyle='#17151d';ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(-25,-84);ctx.lineTo(24,-84);ctx.lineTo(28,-42);ctx.lineTo(4,-38);ctx.lineTo(-2,-59);ctx.lineTo(-12,-38);ctx.lineTo(-31,-42);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#f3e5c4';ctx.fillRect(-24,-82,48,4);
// torso silhouette
ctx.fillStyle=f.skin;ctx.strokeStyle='#17151d';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-23,-132);ctx.quadraticCurveTo(-40,-125,-34,-98);ctx.lineTo(-24,-79);ctx.quadraticCurveTo(0,-71,25,-81);ctx.lineTo(34,-105);ctx.quadraticCurveTo(37,-132,20,-137);ctx.closePath();ctx.fill();ctx.stroke();
// vest/singlet
ctx.fillStyle=f.color;ctx.beginPath();ctx.moveTo(-21,-130);ctx.lineTo(-8,-135);ctx.lineTo(0,-118);ctx.lineTo(10,-136);ctx.lineTo(22,-131);ctx.lineTo(26,-94);ctx.quadraticCurveTo(0,-85,-27,-96);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ffffff33';ctx.fillRect(-17,-123,5,22);
// neck and head
limb(0,-133,0,-146,13,f.skin);ctx.fillStyle=f.skin;ctx.strokeStyle='#17151d';ctx.lineWidth=4;ctx.beginPath();ctx.ellipse(0,-164,23,26,-.04,0,Math.PI*2);ctx.fill();ctx.stroke();
// hair cap
ctx.fillStyle=f===player?'#28232b':'#30231f';ctx.beginPath();ctx.moveTo(-22,-169);ctx.quadraticCurveTo(-26,-195,-5,-192);ctx.quadraticCurveTo(15,-200,23,-181);ctx.lineTo(18,-174);ctx.quadraticCurveTo(0,-181,-22,-169);ctx.fill();
// ear, eye, nose and grin
ctx.fillStyle='#d48b70';ctx.beginPath();ctx.arc(-21,-163,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#20191c';ctx.beginPath();ctx.arc(10,-167,2.5,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#713d3b';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(4,-153);ctx.quadraticCurveTo(11,-149,17,-153);ctx.stroke();ctx.fillStyle='#fff0d3';ctx.beginPath();ctx.arc(1,-180,3,0,Math.PI*2);ctx.fill();
// arms are drawn back arm then forward arm. Punch arm stretches forward (+x local)
let punch=f.punch>0?1-f.punch/(f.punchType==='hook'?.46:.29):0;let swing=Math.sin(punch*Math.PI);const armColor=f.skin, glove=f.glove;
limb(-24,-124,-43,-103,12,armColor);limb(-43,-103,-37,-91,10,armColor);limb(-37,-91,-26,-99,17,glove);ctx.fillStyle='#fff7e2';ctx.font='bold 6px sans-serif';ctx.textAlign='center';ctx.fillText('RR',-26,-97);
let shoulderX=24,shoulderY=-124,elbowX,elbowY,handX,handY;if(punch>.01){elbowX=38+swing*13;elbowY=-111-swing*9;handX=46+swing*58;handY=-116-swing*7}else if(f.guard){elbowX=31;elbowY=-152;handX=34;handY=-171}else{elbowX=43;elbowY=-105+Math.sin(t*4)*3;handX=36;handY=-91+Math.sin(t*4+1)*3}
limb(shoulderX,shoulderY,elbowX,elbowY,12,armColor);limb(elbowX,elbowY,handX-3,handY,11,armColor);ctx.fillStyle=glove;ctx.strokeStyle='#17151d';ctx.lineWidth=3;ctx.beginPath();ctx.ellipse(handX,handY,16,13,-.25,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.fillStyle='#fff7e2';ctx.font='bold 6px sans-serif';ctx.textAlign='center';ctx.fillText('RR',handX,handY+2);ctx.fillStyle='#fae2cf';ctx.fillRect(handX-9,handY+10,18,3);
// badge
ctx.fillStyle='#fff2d6';ctx.font='900 11px sans-serif';ctx.textAlign='center';ctx.fillText(f===player?'1':'?',0,-99);
if(f.hit>0){ctx.strokeStyle='#ffe9ad';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-143,32+Math.sin(t*60)*5,-.4,2.7);ctx.stroke()}
ctx.restore()}
function render(now){const t=now/1000;if(run&&last){let dt=Math.min(.035,(now-last)/1000);tick(dt)}last=now;ctx.save();if(shake>0)ctx.translate(rand(-shake,shake),rand(-shake,shake));arena();drawFighter(enemy,t);drawFighter(player,t);if(flash>0){ctx.fillStyle=`rgba(255,244,206,${flash*1.8})`;ctx.fillRect(0,0,W,H)}ctx.restore();requestAnimationFrame(render)}requestAnimationFrame(render);
})();
</script></body></html>

